import json
import z3

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Message, Data


class RequirementsValidatorComponent(Component):

    display_name = "Z3 Validator"
    description = (
        "Consistency verification using AST constraints "
        "generated by the formalization component."
    )

    inputs = [
        MessageTextInput(
            name="input_data",
            display_name="Formal JSON",
            info="JSON generated by the formalization prompt"
        )
    ]

    outputs = [
        Output(
            name="output",
            display_name="Validation Result",
            method="run_validation"
        )
    ]

    def clean(self, value):

        if isinstance(value, list) and len(value) > 0:
            value = value[0]

        if isinstance(value, Message):
            value = value.text

        elif isinstance(value, Data):
            payload = value.data

            if isinstance(payload, dict):
                value = (
                    payload.get("text")
                    or payload.get("result")
                    or payload
                )
            else:
                value = payload

        if isinstance(value, dict):
            value = json.dumps(value)

        if value is None:
            return ""

        text = str(value).strip()

        if text.startswith("```json"):
            text = text[7:]
        elif text.startswith("```"):
            text = text[3:]

        if text.endswith("```"):
            text = text[:-3]

        return text.strip()

    def get_symbol(self, name, declared_symbols):

        if name not in declared_symbols:
            raise Exception(
                f"Undeclared symbol detected: {name}"
            )

        return declared_symbols[name]

    def ast_to_z3(self, node, declared_symbols):

        node_type = node["type"]

        if node_type == "VAR":
            return self.get_symbol(
                node["name"],
                declared_symbols
            )

        if node_type == "NOT":
            return z3.Not(
                self.ast_to_z3(
                    node["operand"],
                    declared_symbols
                )
            )

        if node_type == "AND":

            operands = []

            for operand in node["operands"]:
                operands.append(
                    self.ast_to_z3(
                        operand,
                        declared_symbols
                    )
                )

            return z3.And(*operands)

        if node_type == "OR":

            operands = []

            for operand in node["operands"]:
                operands.append(
                    self.ast_to_z3(
                        operand,
                        declared_symbols
                    )
                )

            return z3.Or(*operands)

        if node_type == "IMPLIES":

            return z3.Implies(
                self.ast_to_z3(
                    node["antecedent"],
                    declared_symbols
                ),
                self.ast_to_z3(
                    node["consequent"],
                    declared_symbols
                )
            )

        if node_type == "IFF":

            return (
                self.ast_to_z3(
                    node["left"],
                    declared_symbols
                )
                ==
                self.ast_to_z3(
                    node["right"],
                    declared_symbols
                )
            )

        raise Exception(
            f"Unsupported AST node type: {node_type}"
        )

    def build_signature(self, requirement):

        declared_symbols = {}

        signature = requirement.get(
            "z3_signature",
            {}
        )

        predicates = signature.get(
            "predicates",
            []
        )

        constants = signature.get(
            "constants",
            []
        )

        for predicate in predicates:

            name = predicate.get("name")

            if not name:
                continue

            arity = predicate.get("arity", 0)

            if arity == 0:
                declared_symbols[name] = z3.Bool(name)

        for constant in constants:

            if not isinstance(constant, dict):
                continue

            name = constant.get("name")

            if name:
                declared_symbols[name] = z3.Bool(name)

        return declared_symbols

    def run_validation(self) -> Message:

        try:

            text = self.clean(self.input_data)
            data = json.loads(text)

            requirements = data.get(
                "requirements",
                []
            )

            if not requirements:

                return Message(
                    text=json.dumps(
                        {
                            "status": "UNKNOWN",
                            "consistent": False,
                            "message": "No requirements found."
                        },
                        indent=4
                    )
                )

            solver = z3.Solver()

            tracked_requirements = {}

            requirement_ids = []
            traceability = []
            invalid_constraints = []

            total_constraints = 0

            for req in requirements:

                requirement_id = (
                    req.get("requirement_id")
                    or req.get("id")
                    or "UNKNOWN"
                )

                requirement_ids.append(
                    requirement_id
                )

                declared_symbols = (
                    self.build_signature(req)
                )

                ast_constraints = req.get(
                    "ast_constraints",
                    []
                )

                for ast in ast_constraints:

                    try:

                        expr = self.ast_to_z3(
                            ast,
                            declared_symbols
                        )

                        track_symbol = z3.Bool(
                            f"track_{requirement_id}"
                        )
                        
                        tracked_requirements[
                            str(track_symbol)
                        ] = requirement_id
                        
                        solver.assert_and_track(
                            expr,
                            track_symbol
                        )

                        traceability.append(
                            {
                                "requirement_id":
                                    requirement_id,
                                "ast":
                                    ast
                            }
                        )

                        total_constraints += 1

                    except Exception as ex:

                        invalid_constraints.append(
                            {
                                "requirement_id":
                                    requirement_id,
                                "ast":
                                    ast,
                                "error":
                                    str(ex)
                            }
                        )

            if total_constraints == 0:

                return Message(
                    text=json.dumps(
                        {
                            "status": "UNKNOWN",
                            "consistent": False,
                            "requirements":
                                requirement_ids,
                            "constraints": 0,
                            "message":
                                "No AST constraints found.",
                            "traceability":
                                traceability,
                            "invalid_constraints":
                                invalid_constraints
                        },
                        indent=4
                    )
                )

            result = solver.check()
            unsat_core = []

            if result == z3.unsat:
            
                unsat_core = [
                    tracked_requirements[
                        str(x)
                    ]
                    for x in solver.unsat_core()
                    if str(x) in tracked_requirements
                ]

            if result == z3.sat:

                output = {
                    "status": "SAT",
                    "consistent": True,
                    "requirements": requirement_ids,
                    "constraints": total_constraints,
                    "message": "No logical contradiction detected.",
                    "traceability": traceability,
                    "invalid_constraints": invalid_constraints
                }

            elif result == z3.unsat:

                output = {
                    "status": "UNSAT",
                    "consistent": False,
                    "requirements": requirement_ids,
                    "constraints": total_constraints,
                    "message": "Logical contradiction detected.",
                    "unsat_core": unsat_core,
                    "traceability": traceability,
                    "invalid_constraints": invalid_constraints
                }

            else:

                output = {
                    "status": "UNKNOWN",
                    "consistent": False,
                    "requirements": requirement_ids,
                    "constraints": total_constraints,
                    "message":
                        "Logical result inconclusive.",
                    "traceability":
                        traceability,
                    "invalid_constraints":
                        invalid_constraints
                }

            return Message(
                text=json.dumps(
                    output,
                    indent=4
                )
            )

        except Exception as ex:

            return Message(
                text=json.dumps(
                    {
                        "status": "ERROR",
                        "consistent": False,
                        "message": str(ex)
                    },
                    indent=4
                )
            )
            
            if result == z3.unsat:

                unsat_core = [
                    tracked_requirements[str(x)]
                    for x in solver.unsat_core()
                    if str(x) in tracked_requirements
                ]
            
                print("UNSAT CORE:", unsat_core)

from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message

import json
import re


class ASTBuilder(Component):

    display_name = "AST Builder"
    description = (
        "Generates AST constraints and Z3 structures "
        "from formalized requirements."
    )
    icon = "code"
    name = "ASTBuilder"

    inputs = [
        MessageTextInput(
            name="input_value",
            display_name="Formalized JSON"
        )
    ]

    outputs = [
        Output(
            name="output",
            display_name="Formalized AST",
            method="build_output"
        )
    ]

    def normalize(self, text):

        if not text:
            return None

        text = re.sub(
            r"[^A-Za-z0-9_ ]",
            "",
            str(text)
        )

        text = (
            text.replace(" ", "_")
                .replace("-", "_")
        )

        text = re.sub(
            r"_+",
            "_",
            text
        )

        return text.strip("_")

    def parse_input(self):

        text = str(self.input_value).strip()

        if text.startswith("```json"):
            text = text[7:]

        elif text.startswith("```"):
            text = text[3:]

        if text.endswith("```"):
            text = text[:-3]

        return json.loads(text.strip())

    def build_requirement(self, req):

        action = req.get("action")
        condition = req.get("condition")

        if not action:

            req["ast_builder_status"] = (
                "MISSING_ACTION"
            )

            return req

        action_predicate = self.normalize(
            action
        )

        predicates = [
            {
                "name": action_predicate,
                "arity": 0,
                "source": action
            }
        ]

        variables = [
            {
                "name": action_predicate,
                "source": action
            }
        ]

        if condition:

            condition_predicate = (
                self.normalize(condition)
            )

            predicates.append(
                {
                    "name": condition_predicate,
                    "arity": 0,
                    "source": condition
                }
            )

            variables.append(
                {
                    "name": condition_predicate,
                    "source": condition
                }
            )

            ast_constraints = [
                {
                    "type": "IMPLIES",
                    "antecedent": {
                        "type": "VAR",
                        "name":
                            condition_predicate
                    },
                    "consequent": {
                        "type": "VAR",
                        "name":
                            action_predicate
                    }
                }
            ]

            fol_formula = (
                f"{condition_predicate}"
                f" -> "
                f"{action_predicate}"
            )

        else:

            ast_constraints = [
                {
                    "type": "VAR",
                    "name": action_predicate
                }
            ]

            fol_formula = (
                action_predicate
            )

        req["z3_signature"] = {
            "sorts": [],
            "predicates": predicates,
            "functions": [],
            "constants": []
        }

        req["variables"] = variables

        req["fol_formula"] = (
            fol_formula
        )

        req["ast_constraints"] = (
            ast_constraints
        )

        req["constraints"] = [
            {
                "constraint_id": "C1",
                "ast_ref": 0,
                "source":
                    req.get(
                        "source_requirement",
                        action
                    )
            }
        ]

        req["formalization_metadata"] = {
            "translation_confidence": 100,
            "formalization_type":
                "PROPOSITIONAL",
            "variable_count":
                len(variables),
            "constraint_count":
                len(ast_constraints)
        }

        req["consistency_result"] = (
            "READY_FOR_SOLVING"
        )

        req["consistency_explanation"] = ""

        req["ast_builder_status"] = (
            "SUCCESS"
        )

        return req

    def build_output(self) -> Message:

        try:

            data = self.parse_input()

            requirements = data.get(
                "requirements",
                []
            )

            if not requirements:

                result = {
                    "requirements": [],
                    "formalization_summary": {
                        "detected_requirement_count": 0,
                        "processed_count": 0,
                        "formalizable_count": 0,
                        "not_formalizable_count": 0,
                        "formalization_performed": False
                    }
                }

                return Message(
                text=json.dumps(
                    {
                        "DEBUG_AST_OUTPUT": result
                    },
                    indent=2,
                    ensure_ascii=False
                )
            )

            processed = []

            success_count = 0

            for req in requirements:

                req = self.build_requirement(
                    req
                )

                if (
                    req.get(
                        "ast_builder_status"
                    )
                    == "SUCCESS"
                ):
                    success_count += 1

                processed.append(req)

            result = {
                "requirements":
                    processed,

                "formalization_summary": {
                    "detected_requirement_count":
                        len(requirements),

                    "processed_count":
                        len(requirements),

                    "formalizable_count":
                        success_count,

                    "not_formalizable_count":
                        len(requirements)
                        - success_count,

                    "formalization_performed":
                        True
                }
            }

            self.status = result

            return Message(
                text=json.dumps(
                    result,
                    ensure_ascii=False,
                    indent=2
                )
            )

        except Exception as ex:

            error_result = {
                "status": "ERROR",
                "message": str(ex)
            }

            return Message(
                text=json.dumps(
                    error_result,
                    ensure_ascii=False,
                    indent=2
                )
            )

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message

import json


class SignatureValidator(Component):

    display_name = "Signature Validator"
    name = "SignatureValidator"
    description = (
        "Validates symbols used in AST constraints against "
        "the declared z3_signature"
    )

    inputs = [
        MessageTextInput(
            name="input_value",
            display_name="Formalized AST"
        )
    ]

    outputs = [
        Output(
            name="output",
            display_name="Validated AST",
            method="build_output"
        )
    ]

    def collect_symbols(self, node, symbols):

        if not isinstance(node, dict):
            return

        if node.get("type") == "VAR":

            symbol_name = node.get("name")

            if symbol_name:
                symbols.add(symbol_name)

        if "operand" in node:
            self.collect_symbols(
                node["operand"],
                symbols
            )

        if "antecedent" in node:
            self.collect_symbols(
                node["antecedent"],
                symbols
            )

        if "consequent" in node:
            self.collect_symbols(
                node["consequent"],
                symbols
            )

        if "left" in node:
            self.collect_symbols(
                node["left"],
                symbols
            )

        if "right" in node:
            self.collect_symbols(
                node["right"],
                symbols
            )

        for child in node.get(
            "operands",
            []
        ):
            self.collect_symbols(
                child,
                symbols
            )

    def build_output(self) -> Message:

        try:

            raw = (
                self.input_value.text
                if hasattr(
                    self.input_value,
                    "text"
                )
                else str(self.input_value)
            )

            data = json.loads(raw)

        except Exception as e:

            return Message(
                text=json.dumps(
                    {
                        "signature_valid": False,
                        "error": str(e)
                    },
                    indent=2,
                    ensure_ascii=False
                )
            )

        validation_errors = []

        requirements = data.get(
            "requirements",
            []
        )

        for req in requirements:

            declared_symbols = set()

            z3_signature = req.get(
                "z3_signature",
                {}
            )

            for predicate in z3_signature.get(
                "predicates",
                []
            ):

                name = predicate.get("name")

                if name:
                    declared_symbols.add(name)

            for constant in z3_signature.get(
                "constants",
                []
            ):

                name = constant.get("name")

                if name:
                    declared_symbols.add(name)

            used_symbols = set()

            for ast in req.get(
                "ast_constraints",
                []
            ):

                self.collect_symbols(
                    ast,
                    used_symbols
                )

            undeclared_symbols = sorted(
                used_symbols -
                declared_symbols
            )

            if undeclared_symbols:

                validation_errors.append(
                    {
                        "requirement_id":
                            req.get(
                                "requirement_id",
                                "UNKNOWN"
                            ),

                        "error":
                            "UNDECLARED_SYMBOLS",

                        "symbols":
                            undeclared_symbols
                    }
                )

        result = {
            "signature_valid":
                len(validation_errors) == 0,

            "errors":
                validation_errors,

            "requirements":
                requirements
        }

        return Message(
            text=json.dumps(
                result,
                indent=2,
                ensure_ascii=False
            )
        )

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message

import json


class CrossRequirementConsistencyBuilder(Component):

    display_name = "Cross Requirement Consistency Builder"
    name = "CrossRequirementConsistencyBuilder"
    description = "Builds a global AST from multiple requirements"

    inputs = [
        MessageTextInput(
            name="input_value",
            display_name="Validated AST"
        )
    ]

    outputs = [
        Output(
            name="output",
            display_name="Global Logic Model",
            method="build_output"
        )
    ]

    def build_output(self) -> Message:

        try:

            raw = (
                self.input_value.text
                if hasattr(self.input_value, "text")
                else str(self.input_value)
            )

            data = json.loads(raw)

        except Exception as e:

            return Message(
                text=json.dumps(
                    {
                        "error": f"Invalid JSON input: {str(e)}"
                    },
                    indent=2,
                    ensure_ascii=False
                )
            )

        requirements = data.get(
            "requirements",
            []
        )

        global_constraints = []

        participating_requirements = []

        for req in requirements:

            ast_constraints = req.get(
                "ast_constraints",
                []
            )

            if ast_constraints:

                global_constraints.extend(
                    ast_constraints
                )

                participating_requirements.append(
                    req.get(
                        "requirement_id",
                        "UNKNOWN"
                    )
                )

        if not global_constraints:

            global_ast = {
                "status": "NO_CONSTRAINTS"
            }

        elif len(global_constraints) == 1:

            global_ast = global_constraints[0]

        else:

            global_ast = {
                "type": "AND",
                "operands": global_constraints
            }

        result = {
            "participating_requirements":
                participating_requirements,

            "requirement_count":
                len(participating_requirements),

            "global_ast":
                global_ast,

            "requirements":
                requirements
        }

        return Message(
            text=json.dumps(
                result,
                indent=2,
                ensure_ascii=False
            )
        )

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message

import json


class FOLValidator(Component):

    display_name = "FOL Validator"
    name = "FOLValidator"
    description = "Validates and extracts FOL formulas before AST generation"

    inputs = [
        MessageTextInput(
            name="input_value",
            display_name="Formalization JSON"
        )
    ]

    outputs = [
        Output(
            name="output",
            display_name="Validated FOL",
            method="build_output"
        )
    ]

    def build_output(self) -> Message:

        try:

            raw = (
                self.input_value.text
                if hasattr(self.input_value, "text")
                else str(self.input_value)
            )

            data = json.loads(raw)

        except Exception as e:

            return Message(
                text=json.dumps(
                    {
                        "fol_valid": False,
                        "error": str(e)
                    },
                    indent=2,
                    ensure_ascii=False
                )
            )

        errors = []

        for req in data.get(
            "requirements",
            []
        ):

            req_id = req.get(
                "requirement_id",
                "UNKNOWN"
            )

            fol = req.get(
                "fol_formula",
                ""
            )

            if not fol:

                errors.append(
                    {
                        "requirement_id": req_id,
                        "error": "EMPTY_FOL_FORMULA"
                    }
                )

        result = {
            "fol_valid":
                len(errors) == 0,

            "errors":
                errors,

            "requirements":
                data.get(
                    "requirements",
                    []
                )
        }

        return Message(
            text=json.dumps(
                result,
                indent=2,
                ensure_ascii=False
            )
        )

